#!/usr/bin/env bash
# Write deploy/.env with fresh random secrets if it does not exist. Never overwrites.
set -euo pipefail
cd "$(dirname "$0")"
[ -f .env ] && { echo "deploy/.env already exists; leaving it alone"; exit 0; }
rand() { head -c 32 /dev/urandom | base64 | tr -d '\n=+/' | head -c 40; }
fernet() { python3 -c "import base64,os; print(base64.urlsafe_b64encode(os.urandom(32)).decode())"; }
cat > .env <<ENV
# Generated by deploy/init-env.sh. Keep it secret; losing AGENTSHIELD_MASTER_KEY makes stored provider keys unreadable.
POSTGRES_PASSWORD=$(rand)
AGENTSHIELD_APP_PASSWORD=$(rand)
AGENTSHIELD_WORKER_PASSWORD=$(rand)
AGENTSHIELD_MASTER_KEY=$(fernet)
AGENTSHIELD_KEY_PEPPER=$(rand)
AGENTSHIELD_JWT_SECRET=$(rand)
AGENTSHIELD_SESSION_SECRET=$(rand)
ENV
chmod 600 .env
echo "wrote deploy/.env"
